def parse_nested_parens(paren_string: str) -> str:
    groups = paren_string.split()
    def max_depth(s: str) -> int:
        # Filter only parentheses
        filtered = ''.join(c for c in s if c in '()')
        # Use reduce to avoid loops and recursion
        from functools import reduce
        def reducer(acc, c):
            current_depth, max_depth = acc
            if c == '(':
                current_depth += 1
                max_depth = max(max_depth, current_depth)
            elif c == ')':
                current_depth -= 1
            return (current_depth, max_depth)
        _, depth = reduce(reducer, filtered, (0, 0))
        return depth
    depths = list(map(max_depth, groups))
    return ', '.join(str(d) for d in depths)

