def find_solution(a, b, n):
    # We want to find non-negative integers x, y such that a*x + b*y = n
    # Handle special cases where a and/or b are zero
    if a == 0 and b == 0:
        if n == 0:
            return 0, 0
        else:
            return None
    if a == 0:
        if b != 0 and n % b == 0 and n // b >= 0:
            return 0, n // b
        else:
            return None
    if b == 0:
        if a != 0 and n % a == 0 and n // a >= 0:
            return n // a, 0
        else:
            return None

    # Determine max_x for iteration
    # Since x must be non-negative, start from 0
    # If a > 0, max_x = n // a if n >= 0 else 0
    # If a < 0, increasing x decreases a*x, so max_x = 0 if n >= 0 else 0 (no positive x)
    if a > 0:
        max_x = n // a if n >= 0 else 0
    else:
        max_x = 0

    for x in range(max_x + 1):
        remainder = n - a * x
        if b == 0:
            if remainder == 0:
                return x, 0
            else:
                continue
        if remainder % b == 0:
            y = remainder // b
            if y >= 0:
                return x, y
    return None

