def next_smallest_palindrome(num: int) -> int:
    s = str(num)
    length = len(s)

    # If all 9's, the next palindrome is 10...01 (length+1)
    if all(ch == '9' for ch in s):
        return int('1' + ('0' * (length - 1)) + '1')

    # Helper to check if palindrome
    def is_palindrome(x: str) -> bool:
        return x == x[::-1]

    # Generate palindrome by mirroring left to right
    def make_palindrome(left: str, odd_length: bool) -> str:
        if odd_length:
            return left + left[:-1][::-1]
        else:
            return left + left[::-1]

    odd = (length % 2 != 0)
    mid = length // 2

    if odd:
        left = s[:mid+1]
    else:
        left = s[:mid]

    palindrome = make_palindrome(left, odd)

    if int(palindrome) > num:
        return int(palindrome)

    # Increment the left part and form palindrome again
    if odd:
        left_num = int(left)
        left_num += 1
        left = str(left_num)
        # If length changed due to increment (e.g. 999 -> 1000)
        if len(left) > (mid + 1):
            # This means palindrome length increases by 1
            return int('1' + ('0' * (length - 1)) + '1')
        palindrome = make_palindrome(left, odd)
    else:
        left_num = int(left)
        left_num += 1
        left = str(left_num)
        if len(left) > mid:
            return int('1' + ('0' * (length - 1)) + '1')
        palindrome = make_palindrome(left, odd)

    return int(palindrome)

