def substract_elements(t):
    if not isinstance(t, tuple):
        return t
    if len(t) == 0:
        return 0
    if all(not isinstance(x, tuple) for x in t):
        result = t[0]
        for x in t[1:]:
            result -= x
        return result
    # recursive case: subtract elements pairwise
    first = t[0]
    rest = t[1:]
    # recursively subtract rest elements from first element
    def recursive_subtract(a, b):
        if not isinstance(a, tuple) and not isinstance(b, tuple):
            return a - b
        if isinstance(a, tuple) and isinstance(b, tuple):
            length = min(len(a), len(b))
            res = tuple(recursive_subtract(a[i], b[i]) for i in range(length))
            # if a is longer, append remaining elements
            if len(a) > length:
                res += a[length:]
            # if b is longer, subtract remaining elements from 0
            if len(b) > length:
                res += tuple(-b[i] for i in range(length, len(b)))
            return res
        if isinstance(a, tuple):
            # b is scalar, subtract b from each element of a
            return tuple(recursive_subtract(x, b) for x in a)
        if isinstance(b, tuple):
            # a is scalar, subtract each element of b from a
            return tuple(recursive_subtract(a, x) for x in b)
    result = first
    for elem in rest:
        result = recursive_subtract(result, elem)
    return result

