def dif_Square(n):
    # We want to check if n = a^2 - b^2 = (a-b)(a+b) for some integers a,b.
    # Let x = a-b and y = a+b, then n = x*y.
    # Since a and b are integers, x and y must be integers with the same parity (both even or both odd).
    # So we check if n can be factored into two integers x and y with the same parity.
    if n == 0:
        return True  # 0 = 0^2 - 0^2
    abs_n = abs(n)
    for x in range(1, int(abs_n**0.5) + 2):
        if abs_n % x == 0:
            y = abs_n // x
            # Check both (x,y) and (-x,-y) pairs for parity and sign to match n
            for (X, Y) in [(x, y), (-x, -y)]:
                if X % 2 == Y % 2:
                    if X * Y == n:
                        return True
    return False

