    def subtract_pairwise(a, b):
        if isinstance(a, (list, tuple)) and isinstance(b, (list, tuple)):
            if len(a) != len(b):
                raise ValueError("All nested collections must have the same structure and length")
            return type(a)(subtract_pairwise(x, y) for x, y in zip(a, b))
